recipes.code:
{
  "inputs": [
    {
      "id": "filetopdf-api-key",
      "type": "promptString",
      "description": "Your FileToPDF API key (sk_live_...). Get one free in one click at https://filetopdf.dev.",
      "password": true
    }
  ],
  "servers": {
    "filetopdf": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "filetopdf-mcp@0.1.1"
      ],
      "env": {
        "FILETOPDF_API_KEY": "${input:filetopdf-api-key}"
      }
    }
  }
}
